import{_ as a,o as t,a as i,b as o}from"./app.BGziXukh.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"技术附录","link":"/guide/technical_appendix/technical_appendix"},{"text":"浮点计算","link":"/guide/technical_appendix/floating_point_computation/floating_point_computation"},{"text":"浮点操作","link":"/guide/technical_appendix/floating_point_computation/floating_point_operation"}]},"headers":[],"relativePath":"guide/technical_appendix/floating_point_computation/floating_point_operation.md","filePath":"guide/technical_appendix/floating_point_computation/floating_point_operation.md","outlineHeaders":[{"level":2,"title":"概述","slug":"概述","link":"#概述"},{"level":2,"title":"Reg运算","slug":"Reg运算","link":"#Reg运算"},{"level":3,"title":"相关API","slug":"相关API","link":"#相关API"},{"level":2,"title":"SIMT运算","slug":"SIMT运算","link":"#SIMT运算"},{"level":3,"title":"相关API","slug":"相关API-1","link":"#相关API-1"},{"level":2,"title":"Cube运算","slug":"Cube运算","link":"#Cube运算"},{"level":3,"title":"Cube计算单元","slug":"Cube计算单元","link":"#Cube计算单元"},{"level":3,"title":"矩阵计算通路","slug":"矩阵计算通路","link":"#矩阵计算通路"},{"level":3,"title":"相关API","slug":"相关API-2","link":"#相关API-2"}],"lastUpdated":1794984466000}'),l={name:"guide/technical_appendix/floating_point_computation/floating_point_operation.md"};function r(n,e,c,p,_,u){return t(),i("div",null,[...e[0]||(e[0]=[o('<div><article class="markdown-body"><h1>浮点操作</h1><h2 id="概述">概述<a class="header-anchor" href="#概述">​</a></h2><p>本章介绍Ascend C中浮点操作，按API与编程范式分为以下三部分：</p><ul><li><strong>Reg运算</strong>：Reg矢量计算API，以Reg矢量计算寄存器为操作对象的矢量计算，如Add、Mul、Axpy、Cast等。该能力为Ascend 950PR&amp;950DT系列产品新增，属SIMD编程范式。</li><li><strong>SIMT运算</strong>：SIMT编程范式下以线程为粒度的运算，包括内置算术运算符与数学函数，使用方式与C/C++惯用写法一致。</li><li><strong>Cube运算</strong>：Cube核的矩阵计算编程模型，覆盖数据搬入、矩阵乘加到结果搬出（Fixpipe随路量化与ReLU）的完整通路，属SIMD编程范式。</li></ul><h2 id="Reg运算">Reg运算<a class="header-anchor" href="#Reg运算">​</a></h2><p>Reg矢量计算（Reg Vector Compute）是以Reg矢量计算寄存器为操作对象的矢量计算方式，属SIMD编程范式，通过<a href="../../../api/SIMD-API/basic_api/reg_vector_compute/overview.html">Reg矢量计算基础API</a>与<a href="../../../api/SIMD-API/c_api/reg_compute/reg_compute.html">Reg矢量计算C API</a>使用。该能力为Ascend 950PR&amp;950DT系列产品新增。</p><h3 id="相关API">相关API<a class="header-anchor" href="#相关API">​</a></h3><p>Reg运算相关API按层级链接如下，各接口的功能、支持的浮点数据类型及产品支持情况请参见对应文档：</p><ul><li><strong>基础API</strong>：<a href="../../../api/SIMD-API/basic_api/reg_vector_compute/reg_vector_compute.html">Reg矢量计算</a>，涵盖Reg数据搬入与搬出、基础算术（Add、Mul、Div、Exp、Ln、Log等）、复合计算（Axpy、MulDstAdd、Fma等）、精度转换（Cast）、比较与选择、规约、逻辑计算、掩码寄存器操作等；</li><li><strong>C API</strong>：<a href="../../../api/SIMD-API/c_api/reg_compute/reg_compute.html">Reg矢量计算C API</a>，与基础API功能对应，同名函数加<code>asc_</code>前缀（asc_add、asc_fma、asc_float2half等）；</li><li><strong>高阶API</strong>：<a href="../../../api/SIMD-API/adv_api/math_compute/Fma_interface/Fma.html">Fma</a>按元素计算src0 × src1 + src2（单次舍入），操作对象为LocalTensor，通过调用基础API实现，支持half、float。</li></ul><p>各接口的精度标准请参见<a href="../../../api/appendix/reg_vector_compute_interface_precision_standard_summary.html">Reg矢量计算接口精度标准汇总</a>。</p><h2 id="SIMT运算">SIMT运算<a class="header-anchor" href="#SIMT运算">​</a></h2><p>SIMT运算指SIMT编程范式下以线程为粒度执行的浮点运算，运行在AIV核上，通过<a href="../../../api/SIMT-API/overview.html">SIMT API</a>使用。SIMT运算不区分API层次，浮点运算通过两类方式表达：</p><ul><li><strong>C/C++运算符与隐式类型转换</strong>：float、half、bfloat16_t等类型支持<code>+</code>、<code>-</code>、<code>*</code>、<code>/</code>等内置算术运算符和隐式类型转换，使用方式与标准C/C++一致。</li><li><strong>数学函数与类型转换函数</strong>：数学函数与C标准数学库形式对齐。</li></ul><h3 id="相关API-1">相关API<a class="header-anchor" href="#相关API-1">​</a></h3><p>SIMT运算相关API链接如下，各函数的精度标准、Subnormal支持情况及编译选项影响请参见对应文档：</p><ul><li><strong>数学函数</strong>：<a href="../../../api/SIMT-API/math_functions/math_functions.html">SIMT数学函数</a>，按数据类型组织： <ul><li>float类型数学库函数（<code>expf</code>、<code>logf</code>、<code>sinf</code>、<code>fmaf</code>、<code>floorf</code>、<code>isfinite</code>等，与C标准数学库对齐）；</li><li>half类型函数（<code>__hadd</code>、<code>__hfma</code>等算术函数，<code>hexp</code>、<code>hlog</code>等数学库函数，<code>__float2half_rn</code>等精度转换函数，及half短向量版本）；</li><li>bfloat16类型函数（组织方式与half类型一致，前缀同名但作用类型为bfloat16_t，含bfloat16x2短向量版本）；</li><li>fp8类型函数（fp8数据类型简介与数据转换函数）。</li></ul></li><li><strong>数据类型转换</strong>：<a href="../../../api/SIMT-API/math_functions/data_type_conversion/overview.html">SIMT数据类型转换</a>，显式转换API按&quot;源类型2目标类型_舍入模式[_饱和后缀]&quot;命名（如__float2half_rn_sat），隐式转换由编译器自动执行。</li><li><strong>其他SIMT API</strong>（同步、原子操作、Warp函数、访存等）：<a href="../../../api/SIMT-API/overview.html">SIMT API总览</a>。</li></ul><p>各接口的精度标准汇总请参见<a href="../../../api/appendix/SIMT_interface_precision_standard_summary.html">SIMT接口精度标准汇总</a>。</p><h2 id="Cube运算">Cube运算<a class="header-anchor" href="#Cube运算">​</a></h2><p>Cube运算对应Ascend C的矩阵计算编程模型，覆盖Cube核从数据搬入、矩阵乘加到结果搬出的完整通路，属SIMD编程范式。</p><h3 id="Cube计算单元">Cube计算单元<a class="header-anchor" href="#Cube计算单元">​</a></h3><p>AI Core内有三种基础计算单元：Cube计算单元、Vector计算单元和Scalar计算单元。Cube计算单元负责执行矩阵运算，以half数据类型为例，Cube每次执行可完成两个half类型的16x16矩阵的乘法操作。Cube计算单元只能直接访问三个专用缓存：L0A Buffer存储左矩阵，L0B Buffer存储右矩阵，L0C Buffer存储计算结果与累加初值；输入矩阵一般先从Global Memory搬运到空间更大的L1 Buffer，再加载到L0A或L0B。硬件架构详见<a href="../../../api/SIMD-API/basic_api/cube_compute_ISASI/overview/cube_compute_unit.html">矩阵计算单元</a>。</p><h3 id="矩阵计算通路">矩阵计算通路<a class="header-anchor" href="#矩阵计算通路">​</a></h3><p>Ascend C针对矩阵计算编程模型提供了四类接口，分别承载Cube核中各个通路的搬运能力和计算能力：</p><ol><li><strong>数据搬入（DataCopy）</strong>：将A、B原始矩阵及Bias、量化系数等数据从Global Memory搬运到L1 Buffer；</li><li><strong>数据加载（LoadData）</strong>：将A、B矩阵从L1 Buffer加载到L0A Buffer/L0B Buffer准备计算，加载过程中完成分形格式转换；Bias搬运到BiasTable Buffer，量化系数搬运到Fixpipe Buffer；</li><li><strong>矩阵乘加（Mmad）</strong>：对L0A Buffer、L0B Buffer、BiasTable Buffer中的数据执行矩阵乘加C = A × B + C，结果输出到L0C Buffer；</li><li><strong>数据搬出（Fixpipe）</strong>：将L0C Buffer的结果搬运至GM、UB或L1，搬运过程中可利用Fixpipe Buffer中的量化系数、偏置等执行随路量化、随路ReLU、随路通道合并等随路计算。</li></ol><p>矩阵计算的完整流程与各接口详见<a href="../../../api/SIMD-API/basic_api/cube_compute_ISASI/overview/cube_compute_flow.html">矩阵计算流程</a>与<a href="../../../api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI.html">矩阵计算（ISASI）</a>。</p><h3 id="相关API-2">相关API<a class="header-anchor" href="#相关API-2">​</a></h3><p>Cube运算相关API按层级链接如下，各接口的功能与产品支持情况请参见对应文档：</p><ul><li><strong>基础API</strong>：<a href="../../../api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI.html">矩阵计算（ISASI）</a>，涵盖矩阵计算搬入（DataCopy与LoadData）、Mmad计算（Mmad、MmadMx、MmadBitMode、MmadWithSparse）、矩阵计算搬出（Fixpipe）及分形、辅助配置等；</li><li><strong>C API</strong>：<a href="../../../api/SIMD-API/c_api/cube_compute/cube_compute.html">C API矩阵计算</a>，与基础API对应；</li><li><strong>高阶API</strong>：<a href="../../../api/SIMD-API/adv_api/cube_compute/cube_compute.html">Matmul（矩阵计算高阶API）</a>，涵盖Matmul的Kernel侧与Tiling侧接口，封装Tiling切分与流水优化，支持常规Matmul、HF32模式与MxMatmul场景。</li></ul></article></div>',1)])])}const f=a(l,[["render",r]]);export{d as __pageData,f as default};
